{
  "id": "electromagnetic-induction",
  "title": "电磁感应：从磁到电的桥梁",
  "subtitle": "探索法拉第定律、楞次定律及其在现代技术中的力量",
  "language": "zh-CN",
  "audience": "高中学生（物理选修或备考）",
  "theme": "lab",
  "tutor": {
    "suggestions": [
      "磁通量为零时，感应电动势一定为零吗？试举例说明。",
      "楞次定律中的“阻碍”是否意味着感应电流的磁场总是与原磁场反向？",
      "变压器为什么不能直接改变直流电压？如果输入脉动直流呢？",
      "在匀强磁场中平动的导体棒，如果磁场不均匀，如何计算感应电动势？"
    ],
    "kb": [
      {
        "pattern": "磁通量|Φ|magnetic flux",
        "answer": "磁通量是磁场通过某一面积的量度，定义为 Φ = B·S·cosθ，单位韦伯 (Wb)。其变化率决定感应电动势的大小。"
      },
      {
        "pattern": "楞次定律|Lenz's law|来拒去留|增反减同",
        "answer": "感应电流的方向总是阻碍引起感应电流的磁通量变化。这是能量守恒的体现，并非总是与原磁场反向。"
      },
      {
        "pattern": "法拉第电磁感应定律|Faraday's law",
        "answer": "感应电动势与磁通量变化率成正比，ε = -dΦ/dt。负号表示方向（楞次定律）。对于 N 匝线圈，ε = -N dΦ/dt。"
      },
      {
        "pattern": "感生电动势|induced emf|涡旋电场",
        "answer": "由磁场变化产生的电动势，非静电力为涡旋电场力。涡旋电场是非保守场，电场线闭合，不能定义电势。"
      },
      {
        "pattern": "动生电动势|motional emf|切割磁感线",
        "answer": "由导体在磁场中运动产生的电动势，非静电力为洛伦兹力。典型公式 ε = Blv（B、l、v 两两垂直）。"
      },
      {
        "pattern": "自感|self-inductance|互感",
        "answer": "线圈自身电流变化引起感应电动势的现象。自感系数 L = Φ/I，自感电动势 ε_L = -L dI/dt。互感是两线圈间的相互感应。"
      }
    ]
  },
  "scenes": [
    {
      "id": "cover",
      "kind": "hero",
      "notes": "欢迎来到电磁感应的世界。本课将从直观实验出发，逐步深入理论，最后联系工程应用和物理统一性。鼓励学生带着问题思考，注意区分磁通量、磁通量变化和变化率三个易混概念。",
      "blocks": [
        {
          "id": "b_cover",
          "type": "hero",
          "intent": "封面：标题+一句副题，营造科学探索氛围"
        }
      ]
    },
    {
      "id": "magnetic-flux",
      "kind": "content",
      "eyebrow": "概念基础",
      "headline": "磁通量：变化的磁场如何产生电？",
      "lead": "磁通量 Φ = BS 是理解电磁感应的钥匙，其变化率直接决定感应电动势。",
      "notes": "强调磁通量是标量，但有正负，取决于方向。有效面积是垂直于磁场方向的投影。磁通量变化有三种方式：B 变、S 变、θ 变。常见误区：Φ = 0 时感应电动势不一定为零，关键看变化率。例如线圈平面与磁场平行时 Φ = 0，但转动时变化率最大。",
      "blocks": [
        {
          "id": "p2_b1",
          "type": "statement",
          "intent": "定义磁通量及其变化，强调变化率才是关键"
        },
        {
          "id": "p2_b2",
          "type": "flow",
          "intent": "展示磁通量变化的三种途径：B 变、S 变、θ 变，并给出具体例子"
        }
      ]
    },
    {
      "id": "lenz-law",
      "kind": "content",
      "eyebrow": "实验与直觉",
      "headline": "楞次定律：感应电流的“惯性”",
      "lead": "感应电流的方向总是阻碍引起感应电流的磁通量变化。",
      "notes": "经典实验：磁铁插入线圈，感应电流产生反向磁场阻碍插入；拔出时产生同向磁场阻碍拔出。口诀“增反减同”“来拒去留”。能量守恒解释：如果感应电流方向相反，会吸引磁铁加速，导致能量无中生有。强调“阻碍”不是“阻止”，变化仍在进行。",
      "blocks": [
        {
          "id": "p3_b1",
          "type": "compare",
          "intent": "对比磁铁插入与拔出时感应电流方向、磁场变化及效果"
        },
        {
          "id": "p3_b2",
          "type": "callout",
          "intent": "强调楞次定律是能量守恒的体现，并非总是反向"
        }
      ]
    },
    {
      "id": "faraday-law",
      "kind": "content",
      "eyebrow": "定量描述",
      "headline": "法拉第电磁感应定律：变化率决定电动势",
      "lead": "感应电动势的大小与磁通量变化率成正比，ε = -dΦ/dt。",
      "notes": "公式中的负号是楞次定律的数学表达。对于多匝线圈，ε = -N dΦ/dt。区分感生电动势（磁场变化）和动生电动势（导体切割磁感线）。简单实例：匀强磁场中导体棒平动，ε = Blv。注意适用条件：B、l、v 两两垂直。",
      "blocks": [
        {
          "id": "p4_b1",
          "type": "formula",
          "intent": "展示法拉第定律公式 ε = -dΦ/dt 及其多匝形式",
          "latex": "\\varepsilon = -\\frac{d\\Phi}{dt}"
        },
        {
          "id": "p4_b2",
          "type": "list",
          "intent": "列举感生与动生电动势的典型实例及适用条件"
        }
      ]
    },
    {
      "id": "induced-motional-emf",
      "kind": "content",
      "eyebrow": "微观机制",
      "headline": "非静电力：涡旋电场与洛伦兹力",
      "lead": "感生电动势源于涡旋电场，动生电动势源于洛伦兹力。",
      "notes": "感生电场（涡旋电场）是非保守场，电场线闭合，不能定义电势。动生电动势微观推导：导体中电子受洛伦兹力 F = -e(v×B)，非静电力做功。ε = Blv 的适用条件：B、l、v 两两垂直。若磁场不均匀，需用积分 ε = ∫(v×B)·dl。两者在回路中可共存。",
      "blocks": [
        {
          "id": "p5_b1",
          "type": "compare",
          "intent": "对比感生电场与静电场的性质：保守性、电场线、电势定义"
        },
        {
          "id": "p5_b2",
          "type": "flow",
          "intent": "动生电动势的微观推导步骤：洛伦兹力→非静电力→电动势"
        }
      ]
    },
    {
      "id": "self-inductance",
      "kind": "content",
      "eyebrow": "电路中的电磁感应",
      "headline": "自感：线圈自己的“惯性”",
      "lead": "自感系数 L 表征线圈对电流变化的阻碍能力，ε_L = -L dI/dt。",
      "notes": "自感现象：闭合开关时灯泡渐亮，断开时产生高压。从磁通量角度：电流变化→磁场变化→磁通量变化→感应电动势。L 的定义：L = Φ/I。互感类似，两个线圈相互影响。变压器就是基于互感原理。",
      "blocks": [
        {
          "id": "p6_b1",
          "type": "formula",
          "intent": "自感电动势公式及 L 的定义",
          "latex": "\\varepsilon_L = -L \\frac{dI}{dt}"
        },
